    const slice = (f, shade, shadow) => { ctx.save(); ctx.setTransform(M0); if(shadow){ ctx.shadowColor='rgba(0,0,0,.38)'; ctx.shadowBlur=Math.max(4, T*0.7); ctx.shadowOffsetX=ex*0.6; ctx.shadowOffsetY=Math.abs(ey)*0.8 + Math.max(2, T*0.25); } ctx.translate(ex*f, ey*f); V(); ctx.strokeStyle=shade; ctx.fillStyle=shade; ctx.lineWidth=T; paint(shade); ctx.restore(); };
